def transform(grid):
    """Extend the color of the inner block two cells beyond the enclosing frame."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    # The color occurring strictly inside the frame is the extension color.
    counts = {}
    for r, c, v in cells:
        counts[v] = counts.get(v, 0) + 1
    frame_color = max(counts, key=counts.get)
    inner_colors = [v for _, _, v in cells if v != frame_color]
    fill = inner_colors[0] if inner_colors else frame_color
    r0, r1 = min(r for r, _, _ in cells), max(r for r, _, _ in cells)
    c0, c1 = min(c for _, c, _ in cells), max(c for _, c, _ in cells)
    out = [row[:] for row in grid]
    for r in range(max(0, r0-2), min(h, r1+3)):
        for c in range(max(0, c0-2), min(w, c1+3)):
            if grid[r][c] == 0:
                out[r][c] = fill
    return out
