def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if not colors:
        return [row[:] for row in grid]
    # The common color is the rectangle; the contrasting inner color expands outward.
    counts = {v: sum(row.count(v) for row in grid) for v in colors}
    frame = max(colors, key=counts.get)
    accent = min(colors, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    ap = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == accent]
    ar0, ar1 = min(r for r, c in ap), max(r for r, c in ap)
    ac0, ac1 = min(c for r, c in ap), max(c for r, c in ap)
    # A rectangular inset makes the surrounding frame thickness the extension distance;
    # an isolated marker instead gets a one-cell extension.
    rect = all(grid[r][c] == accent for r in range(ar0, ar1 + 1) for c in range(ac0, ac1 + 1))
    margins = (ar0-r0, r1-ar1, ac0-c0, c1-ac1)
    pad = margins[0] if rect and min(margins) > 0 and len(set(margins)) == 1 else 1
    out = [row[:] for row in grid]
    for r in range(max(0, r0-pad), min(h, r1+pad+1)):
        for c in range(max(0, c0-pad), min(w, c1+pad+1)):
            if grid[r][c] == 0:
                out[r][c] = accent
    return out
